const args = $input.first().json;
if (!args.tecnologia || String(args.tecnologia).trim() === '') {
  return [{ json: { status: 'ERROR', message_to_agent: 'Faltó parámetro tecnologia. Valores válidos: DTF Textil, DTF UV, UV, Sublimación, Eco-Solvente, Solvente, RISO, IDL Láser, Gran Formato, Corte.', _skip: true } }];
}
return [{ json: args }];

// v2 — Fix F1: filtra records vacíos antes de procesar.
// Airtable con alwaysOutputData=true devuelve [{}] cuando no hay match; sin este
// filtro, el Format Output ve length=1 y devuelve RESOLVED con campos undefined.

const matches = $input.all().filter(m => m.json && m.json.id && m.json.Nombre);
const args = $('Execute Workflow Trigger').first().json;

if (matches.length === 0) {
  return [{ json: {
    status: 'NOT_FOUND',
    data: null,
    message_to_agent: `No encontré la tecnología "${args.tecnologia}". Las disponibles son: DTF Textil, DTF UV, UV, Sublimación, Eco-Solvente, Solvente, RISO, IDL Láser, Gran Formato, Corte. Verificá el nombre exacto.`,
    trace_id: $execution.id
  } }];
}

const rec = matches[0].json;
return [{ json: {
  status: 'RESOLVED',
  data: {
    nombre: rec.Nombre,
    descripcion_larga: rec['Descripción larga'] || '',
    materiales_recomendados: rec['Materiales recomendados'] || '',
    restricciones: rec['Restricciones / Limitaciones'] || '',
    aplicaciones_tipicas: rec['Aplicaciones típicas'] || '',
    linea_principal: rec['Línea principal'] || ''
  },
  message_to_agent: `Ficha técnica de ${rec.Nombre} cargada. Usá la información para responder al cliente con tono natural.`,
  trace_id: $execution.id
} }];
